import{_ as r,c as a,o as n,ag as t}from"./chunks/framework.CQuhCYrb.js";const c=JSON.parse('{"title":"Community Reading List","description":"","frontmatter":{"title":"Community Reading List"},"headers":[],"relativePath":"community/community-reading-list.md","filePath":"community/community-reading-list.md","lastUpdated":null}'),o={name:"community/community-reading-list.md"};function i(l,e,s,h,d,g){return n(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="community-reading-list" tabindex="-1">Community Reading List <a class="header-anchor" href="#community-reading-list" aria-label="Permalink to &quot;Community Reading List&quot;">​</a></h1><h2 id="community-recommended-reading-and-listening-list" tabindex="-1">Community Recommended Reading and Listening List <a class="header-anchor" href="#community-recommended-reading-and-listening-list" aria-label="Permalink to &quot;Community Recommended Reading and Listening List&quot;">​</a></h2><ol><li><p>2025</p></li><li><p>2023</p></li></ol><h3 id="leadership" tabindex="-1">Leadership <a class="header-anchor" href="#leadership" aria-label="Permalink to &quot;Leadership&quot;">​</a></h3><p>For the full DFP Guides, see <a href="/general/dfp-guide.html">Guide</a>.</p><p>This section provides a list of recommended readings on leadership:</p><ul><li><p><strong><a href="https://www.amazon.com/The-Infinite-Game-Simon-Sinek-audiobook/dp/B07DKHFTB7" target="_blank" rel="noreferrer">The Infinite Game</a> by Simon Sinek</strong></p></li><li><p><strong><a href="https://www.amazon.com/Start-Why-Leaders-Inspire-Everyone/dp/1591846447/" target="_blank" rel="noreferrer">Start with Why: How Great Leaders Inspire Everyone to Take Action</a> by Simon Sinek</strong></p></li><li><p><strong><a href="https://www.amazon.com/Leaders-Eat-Last-Together-Others/dp/B00C1N9JG6/" target="_blank" rel="noreferrer">Leaders Eat Last: Why Some Teams Pull Together and Others Don’t</a> by Simon Sinek</strong></p></li><li><p><strong><a href="https://www.amazon.com/Thoughts-Philosophical-Fighter-Pilot-Reprint/dp/0817993924" target="_blank" rel="noreferrer">Thoughts of a Philosophical Fighter Pilot</a></strong></p></li></ul><h3 id="influence" tabindex="-1">Influence <a class="header-anchor" href="#influence" aria-label="Permalink to &quot;Influence&quot;">​</a></h3><h4 id="information-operations" tabindex="-1">Information Operations <a class="header-anchor" href="#information-operations" aria-label="Permalink to &quot;Information Operations&quot;">​</a></h4><ul><li><p><strong><a href="https://a.co/d/5lfcn0H" target="_blank" rel="noreferrer">Putin’s Trolls: On the Frontlines of Russia’s Information War Against the World</a> by Jessikka Aro</strong></p></li><li><p><strong><a href="https://a.co/d/7mLQThx" target="_blank" rel="noreferrer">Disinformation: Former Spy Chief Reveals Secret Strategies for Undermining Freedom, Attacking Religion, and Promoting Terrorism</a> by Gen Ion Mihai Pacepa, Prof Ronald J Rychlak</strong></p></li></ul><h4 id="social-engineering" tabindex="-1">Social Engineering <a class="header-anchor" href="#social-engineering" aria-label="Permalink to &quot;Social Engineering&quot;">​</a></h4><ul><li><p><strong><a href="https://www.amazon.com/Social-Engineering-Second-Science-Hacking/dp/B07NS53TKR/" target="_blank" rel="noreferrer">Social Engineering: The Science of Human Hacking</a> by Christopher J. Hadnagy</strong></p></li><li><p><strong><a href="https://www.amazon.com/Click-Forces-Behind-Engage-Everything/dp/0385529066/" target="_blank" rel="noreferrer">Click: The Forces Behind How We Fully Engage with People, Work, and Everything We Do</a> by Ori Brafman</strong></p></li><li><p><strong><a href="https://www.amazon.com/gp/product/B000S1LU3M/" target="_blank" rel="noreferrer">The Starfish and the Spider: The Unstoppable Power of Leaderless Organizations</a> by Ori Brafman and Rod</strong></p></li><li><p><strong><a href="https://www.amazon.com/Power-Persuasion-Were-Bought-Sold/dp/0471266341/" target="_blank" rel="noreferrer">The Power of Persuasion: How We’re Bought and Sold</a> by Robert Levine</strong></p></li></ul><h3 id="society" tabindex="-1">Society <a class="header-anchor" href="#society" aria-label="Permalink to &quot;Society&quot;">​</a></h3><ul><li><p><strong><a href="https://www.amazon.com/Propaganda-Edward-Bernays/dp/0970312598/" target="_blank" rel="noreferrer">Propaganda</a> by Edward Bernays</strong></p></li><li><p><strong><a href="https://www.amazon.com/Manufacturing-Consent-Political-Economy-Media/dp/0375714499/" target="_blank" rel="noreferrer">Manufacturing Consent: The Political Economy of the Mass Media</a> by Edward S. Herman and Noam Chomsky</strong></p></li><li><p><strong><a href="https://www.amazon.com/Mistakes-Were-Made-but-Third/dp/0358329612/" target="_blank" rel="noreferrer">Mistakes Were Made (but Not By Me) Third Edition</a> by Carol Tavris</strong></p></li></ul><h3 id="modeling" tabindex="-1">Modeling <a class="header-anchor" href="#modeling" aria-label="Permalink to &quot;Modeling&quot;">​</a></h3><h4 id="applied-predictive-modeling" tabindex="-1">Applied Predictive Modeling <a class="header-anchor" href="#applied-predictive-modeling" aria-label="Permalink to &quot;Applied Predictive Modeling&quot;">​</a></h4><ul><li><strong><a href="https://www.amazon.com/Applied-Predictive-Modeling-Max-Kuhn/dp/1461468485" target="_blank" rel="noreferrer">Applied Predictive Modeling</a> by Max Kuhn and Kjell Johnson</strong><ul><li><a href="https://vuquangnguyen2016.files.wordpress.com/2018/03/applied-predictive-modeling-max-kuhn-kjell-johnson_1518.pdf" target="_blank" rel="noreferrer">pdf link</a></li></ul></li></ul><h3 id="psychology" tabindex="-1">Psychology <a class="header-anchor" href="#psychology" aria-label="Permalink to &quot;Psychology&quot;">​</a></h3><ul><li><p><strong><a href="https://www.amazon.com/Influence-Psychology-Persuasion-Robert-Cialdini/dp/006124189X/" target="_blank" rel="noreferrer">Influence: The Psychology of Persuasion</a> by Robert Cialdini</strong></p></li><li><p><strong><a href="https://www.amazon.com/Thinking-Fast-Slow-Daniel-Kahneman/dp/0374533555/" target="_blank" rel="noreferrer">Thinking, Fast and Slow</a> by Daniel Kahneman</strong></p></li></ul><h4 id="open-source-warfare" tabindex="-1">Open Source Warfare <a class="header-anchor" href="#open-source-warfare" aria-label="Permalink to &quot;Open Source Warfare&quot;">​</a></h4><ul><li><p><strong><a href="https://www.amazon.com/Brave-New-War-Terrorism-Globalization/dp/0471780790/" target="_blank" rel="noreferrer">Brave New War: The Next Stage of Terrorism and the End of Globalization</a> by John Robb</strong></p></li><li><p><strong><a href="https://www.amazon.com/LikeWar-Weaponization-P-W-Singer/dp/0358108470/" target="_blank" rel="noreferrer">LikeWar: The Weaponization of Social Media</a> by P.W. Singer</strong></p></li><li><p><strong><a href="https://www.amazon.com/Sovereign-Individual-Mastering-Transition-Information/dp/0684832720/" target="_blank" rel="noreferrer">The Sovereign Individual: Mastering the Transition to the Information Age</a> by James Dale Davidson and Lord William Rees-Mogg</strong></p></li></ul><h4 id="crowd-psychology" tabindex="-1">Crowd Psychology <a class="header-anchor" href="#crowd-psychology" aria-label="Permalink to &quot;Crowd Psychology&quot;">​</a></h4><ul><li><p><strong><a href="https://www.amazon.com/True-Believer-Thoughts-Movements-Perennial-ebook/dp/B003TO5838/" target="_blank" rel="noreferrer">The True Believer: Thoughts on the Nature of Mass Movements</a> by Eric Hoffer</strong></p></li><li><p><strong><a href="https://www.amazon.com/Crowd-Study-Popular-Mind-ebook/dp/B0B3NM64GX/" target="_blank" rel="noreferrer">The Crowd: A Study of the Popular Mind</a> by Gustave Le Bon</strong></p></li><li><p><strong><a href="https://www.amazon.com/Memoirs-Extraordinary-Popular-Delusions-Volu-ebook/dp/B0B3NKR3RN" target="_blank" rel="noreferrer">Memoirs of Extraordinary Popular Delusions</a> by Charles Mackay</strong></p></li><li><p><strong><a href="https://www.amazon.com/PUBLIC-OPINION-Walter-Lippmann-ebook/dp/B075R63RHB" target="_blank" rel="noreferrer">PUBLIC OPINION</a> by Walter Lippmann</strong></p></li></ul><h4 id="foreign-perspectives-of-america" tabindex="-1">Foreign Perspectives of America <a class="header-anchor" href="#foreign-perspectives-of-america" aria-label="Permalink to &quot;Foreign Perspectives of America&quot;">​</a></h4><ul><li><p><strong><a href="https://www.amazon.com/Understanding-Anti-Americanism-Origins-Impact-Abroad/dp/1566636167" target="_blank" rel="noreferrer">Understanding Anti-Americanism</a> by Paul Hollander</strong></p></li><li><p><strong><a href="https://www.amazon.com/Land-Without-Ghosts-Impressions-Mid-Nineteenth/dp/0520084241" target="_blank" rel="noreferrer">Land without Ghosts</a> by David Arkush</strong></p></li><li><p><strong><a href="https://www.amazon.com/Hating-America-History-Barry-Rubin/dp/019530649X/" target="_blank" rel="noreferrer">Hating America</a> by Barry Rubin</strong></p></li><li><p><strong><a href="https://www.amazon.com/Ugly-American-WILLIAM-J-LEDERER/dp/B0B1C3K6W2/" target="_blank" rel="noreferrer">Ugly American</a> by William J Lederer</strong></p></li></ul><h3 id="war" tabindex="-1">War <a class="header-anchor" href="#war" aria-label="Permalink to &quot;War&quot;">​</a></h3><ul><li><p><strong><a href="https://www.amazon.com/Triple-Cross-Ladens-Penetrate-September/dp/0061189411/" target="_blank" rel="noreferrer">Triple Cross: How bin Laden’s Master Spy Penetrated the CIA, the Green Berets, and the FBI</a> by Peter Lance</strong></p></li><li><p><strong><a href="https://www.amazon.com/Ghost-Wars-Secret-Afghanistan-September/dp/0143034669/" target="_blank" rel="noreferrer">Ghost Wars: The Secret History of the CIA, Afghanistan, and Bin Laden, from the Soviet Invasion to September 10, 2001</a> by Steve Coll</strong></p></li><li><p><strong><a href="https://www.amazon.com/War-Racket-Antiwar-Americas-Decorated/dp/0922915865/" target="_blank" rel="noreferrer">War Is a Racket: The Antiwar Classic by America’s Most Decorated Soldier</a> by Smedley D. Butler</strong></p></li><li><p><strong><a href="https://www.amazon.com/Art-War-Sun-Tzu/dp/1599869772/" target="_blank" rel="noreferrer">The Art of War</a> by Sun Tzu</strong></p></li><li><p><strong><a href="https://www.amazon.com/Face-Battle-Agincourt-Waterloo-Somme/dp/0140048979/" target="_blank" rel="noreferrer">The Face of Battle: A Study of Agincourt, Waterloo, and the Somme</a> by John Keegan</strong></p></li><li><p><strong><a href="https://www.amazon.com/Guns-August-Barbara-W-Tuchman/dp/0345476093/" target="_blank" rel="noreferrer">The Guns of August</a> by Barbara W. Tuchman</strong></p></li><li><p><strong><a href="https://www.amazon.com/Making-Atomic-Bomb-Richard-Rhodes/dp/1451677618/" target="_blank" rel="noreferrer">The Making of the Atomic Bomb</a> by Richard Rhodes</strong></p></li></ul><h3 id="intelligence-research-and-analysis" tabindex="-1">Intelligence, Research, and Analysis <a class="header-anchor" href="#intelligence-research-and-analysis" aria-label="Permalink to &quot;Intelligence, Research, and Analysis&quot;">​</a></h3><h4 id="rss" tabindex="-1">RSS <a class="header-anchor" href="#rss" aria-label="Permalink to &quot;RSS&quot;">​</a></h4><ul><li><a href="https://ni-u.edu/wp/research-shorts-and-notes/" target="_blank" rel="noreferrer">Research Shorts and Notes</a></li></ul><h4 id="intelligence-gathering-and-analysis" tabindex="-1">Intelligence Gathering and Analysis <a class="header-anchor" href="#intelligence-gathering-and-analysis" aria-label="Permalink to &quot;Intelligence Gathering and Analysis&quot;">​</a></h4><ul><li><p><strong>[Psychology of Intelligence Analysis</strong></p></li><li><p><strong><a href="https://www.amazon.com/Psychology-Intelligence-Analysis-Richards-Heuer/dp/1684224128/" target="_blank" rel="noreferrer">https://www.amazon.com/Art-Intelligence-Lessons-Clandestine-Service/dp/0143123370/ The Art of Intelligence: Lessons from a Life in the CIA’s Clandestine Service</a> by Henry A. Crumpton</strong></p></li><li><p><strong><a href="https://www.amazon.com/Craft-Intelligence-Legendary-Fundamentals-Gathering/dp/1591145180/" target="_blank" rel="noreferrer">The Craft of Intelligence: America’s Legendary Spy Master on the Fundamentals of Intelligence Gathering for a Free World</a> by Allen W. Dulles</strong></p></li><li><p><strong><a href="https://www.amazon.com/Secret-World-History-Intelligence/dp/0300243874/" target="_blank" rel="noreferrer">The Secret World: A History of Intelligence</a> by Christopher Andrew</strong></p></li></ul><h4 id="research-and-analysis" tabindex="-1">Research and Analysis <a class="header-anchor" href="#research-and-analysis" aria-label="Permalink to &quot;Research and Analysis&quot;">​</a></h4><ul><li><p><strong><a href="https://www.amazon.com/Analysis-Financial-Statements-Gerald-White/dp/0470890810/" target="_blank" rel="noreferrer">The Analysis and Use of Financial Statements</a> by Gerald I. White and Ashwinpaul C. Sondhi</strong></p></li><li><p><strong><a href="https://www.amazon.com/Elements-Statistical-Learning-Prediction-Statistics/dp/0387848576/" target="_blank" rel="noreferrer">The Elements of Statistical Learning: Data Mining, Inference, and Prediction, Second Edition</a> by Trevor Hastie, Robert Tibshirani, and Jerome Friedman</strong></p></li><li><p><strong><a href="https://www.amazon.com/Signal-Noise-Many-Predictions-Fail-but/dp/0143125087/" target="_blank" rel="noreferrer">The Signal and the Noise: Why So Many Predictions Fail — but Some Don’t</a> by Nate Silver</strong></p></li><li><p><strong><a href="https://a.co/d/2C990an" target="_blank" rel="noreferrer">Knowing What We Know</a></strong></p></li></ul><h3 id="technology" tabindex="-1">Technology <a class="header-anchor" href="#technology" aria-label="Permalink to &quot;Technology&quot;">​</a></h3><ul><li><p><strong><a href="https://www.amazon.com/Genius-Makers-Mavericks-Brought-Facebook/dp/B08CYBGCR1/" target="_blank" rel="noreferrer">Genius Makers</a> by Cade Metz, John Lee, et al.</strong></p></li><li><p><strong><a href="https://www.amazon.com/The-Information-James-Gleick-audiobook/dp/B004Q3NKK4/" target="_blank" rel="noreferrer">The Information</a> by James Gleick, Rob Shapiro, et al.</strong></p></li><li><p><strong><a href="https://www.amazon.com/Ghost-Wires-Adventures-Worlds-Wanted-ebook/dp/B0047Y0F0K/" target="_blank" rel="noreferrer">Ghost in the Wires: My Adventures as the World’s Most Wanted Hacker</a> by Kevin Mitnick</strong></p></li></ul><h4 id="cybersecurity" tabindex="-1">Cybersecurity <a class="header-anchor" href="#cybersecurity" aria-label="Permalink to &quot;Cybersecurity&quot;">​</a></h4><ul><li><p><strong><a href="https://www.amazon.com/Cuckoos-Egg-Tracking-Computer-Espionage/dp/1416507787/" target="_blank" rel="noreferrer">The Cuckoo’s Egg: Tracking a Spy Through the Maze of Computer Espionage</a> by Cliff Stoll</strong></p></li><li><p><strong><a href="https://www.amazon.com/dp/1681774593/" target="_blank" rel="noreferrer">Cyber Spies</a> by Gordon Corera</strong></p></li><li><p><strong><a href="https://www.amazon.com/Sandworm-Cyberwar-Kremlins-Dangerous-Hackers/dp/0385544405/" target="_blank" rel="noreferrer">Sandworm: A New Era of Cyberwar and the Hunt for the Kremlin’s Most Dangerous Hackers</a> by Andy Greenberg</strong></p></li></ul><h4 id="blockchain" tabindex="-1">Blockchain <a class="header-anchor" href="#blockchain" aria-label="Permalink to &quot;Blockchain&quot;">​</a></h4><ul><li><p><strong>On Constellation:</strong></p><ul><li><a href="https://medium.com/@lee.papa/the-unique-value-proposition-and-bull-case-for-constellation-network-1c260dc03f23" target="_blank" rel="noreferrer">The Unique Value Proposition and Bull Case for Constellation Network</a></li><li><a href="https://medium.com/@lee.papa/a-brief-history-of-the-hypergraph-1d8f79fd72e5" target="_blank" rel="noreferrer">A Brief History of the Hypergraph</a></li></ul></li><li><p><strong>On Void:</strong></p><ul><li><a href="https://enterthevoidnft.medium.com/" target="_blank" rel="noreferrer">Enter the Void NFT</a></li></ul></li></ul><h3 id="philosophy" tabindex="-1">Philosophy <a class="header-anchor" href="#philosophy" aria-label="Permalink to &quot;Philosophy&quot;">​</a></h3><ul><li><p><strong><a href="https://www.amazon.com/Meditations-Marcus-Aurelius/dp/1503280462/" target="_blank" rel="noreferrer">Meditations</a> by Marcus Aurelius</strong></p></li><li><p><strong>[Enchiridion: Epictetus, Robert M. Baird et al.</strong></p></li></ul><p>[Engineering]</p>',43)])])}const m=r(o,[["render",i]]);export{c as __pageData,m as default};
